/// <summary>
/// Bug 286663: CB705- Vendor deals are not filtering based on the header vendor account
/// </summary>
[ExtensionOf(classStr(TAMRebateQueryBuilderPurchOrder))]
final class METTAMRebateQueryBuilderPurchOrder_Extension
{
}

Method.Source:
/// <summary>
/// Add the vendor account filter as it is not handled by header attributes like customer
/// </summary>
protected void addTransRange()
{
    next addTransRange();

    // Filter transactions by the deal custom vendor account
    this.metAddVendAccountRange();
}

/// <summary>
/// Bug 296923: CB705 - Inclusive Product Hierarchies filter is not working to generate vendor rebate
/// because we have rebateTable.RebateAgreementType, TAMRebateQueryBuilder_GlobalUnifiedPricing_Extension\requireOrderAccount is forcing
/// requireOrderAccount to return true.
/// Regardless of requireOrderAccount, Metcash requirement is to always use InvoiceAccount for vendor rebates.
/// </summary>
/// <returns>Transaction invoice account</returns>
public FieldId accountJourTableFieldId()
{
    // Std code commented from parent class
    /*if (this.requireOrderAccount())
    {
        return this.orderAccountJourTableFieldId();
    }*/
    FieldId fieldId = next accountJourTableFieldId();

    return this.invoiceAccountJourTableFieldId();
}
